from __future__ import annotations

import logging
from dataclasses import dataclass, field
from enum import Enum

logger = logging.getLogger(__name__)


class CapabilityDimension(str, Enum):
    REASONING = "reasoning"
    PLANNING = "planning"
    TOOL_USE = "tool_use"
    MEMORY = "memory"
    SELF_REFLECTION = "self_reflection"
    KNOWLEDGE = "knowledge"
    COLLABORATION = "collaboration"
    SAFETY = "safety"
    AUTONOMY = "autonomy"
    MULTI_MODAL = "multi_modal"
    ADAPTATION = "adaptation"
    INNOVATION = "innovation"


class RequiredLevel(str, Enum):
    CRITICAL = "critical"
    IMPORTANT = "important"
    NICE_TO_HAVE = "nice_to_have"


class BeeVerseStatus(str, Enum):
    INSTALLED = "installed"
    PARTIAL = "partial"
    MISSING = "missing"


@dataclass
class CapabilityItem:
    name: str
    dimension: CapabilityDimension
    description: str
    required_level: RequiredLevel
    beeverse_status: BeeVerseStatus
    beeverse_match: str = ""
    formula_suggestion: str = ""


class AgenticAICapabilityFramework:
    def __init__(self):
        self._capabilities: list[CapabilityItem] = []
        self._name_index: dict[str, CapabilityItem] = {}
        self._init_capabilities()

    def _init_capabilities(self):
        self._capabilities = [            *self._reasoning_capabilities(),
            *self._planning_capabilities(),
            *self._tool_use_capabilities(),
            *self._memory_capabilities(),
            *self._self_reflection_capabilities(),
            *self._knowledge_capabilities(),
            *self._collaboration_capabilities(),
            *self._safety_capabilities(),
            *self._autonomy_capabilities(),
            *self._multi_modal_capabilities(),
            *self._adaptation_capabilities(),
            *self._innovation_capabilities(),        ]
        self._name_index = {c.name: c for c in self._capabilities}

