    def get_all_capabilities(self) -> list[CapabilityItem]:
        return list(self._capabilities)

    def get_capabilities_by_dimension(self, dimension: CapabilityDimension) -> list[CapabilityItem]:
        return [c for c in self._capabilities if c.dimension == dimension]

    def get_missing_capabilities(self) -> list[CapabilityItem]:
        return [c for c in self._capabilities if c.beeverse_status == BeeVerseStatus.MISSING]

    def get_partial_capabilities(self) -> list[CapabilityItem]:
        return [c for c in self._capabilities if c.beeverse_status == BeeVerseStatus.PARTIAL]

    def get_critical_gaps(self) -> list[CapabilityItem]:
        return [
            c for c in self._capabilities
            if c.beeverse_status != BeeVerseStatus.INSTALLED and c.required_level == RequiredLevel.CRITICAL
        ]

    def get_coverage_summary(self) -> dict:
        dimension_stats: dict[str, dict] = {}
        for dim in CapabilityDimension:
            caps = self.get_capabilities_by_dimension(dim)
            total = len(caps)
            installed = sum(1 for c in caps if c.beeverse_status == BeeVerseStatus.INSTALLED)
            partial = sum(1 for c in caps if c.beeverse_status == BeeVerseStatus.PARTIAL)
            missing = sum(1 for c in caps if c.beeverse_status == BeeVerseStatus.MISSING)
            coverage_pct = (installed + 0.5 * partial) / total * 100 if total > 0 else 0.0
            dimension_stats[dim.value] = {
                "total": total,
                "installed": installed,
                "partial": partial,
                "missing": missing,
                "coverage_pct": round(coverage_pct, 2),
            }

        total_all = len(self._capabilities)
        installed_all = sum(1 for c in self._capabilities if c.beeverse_status == BeeVerseStatus.INSTALLED)
        partial_all = sum(1 for c in self._capabilities if c.beeverse_status == BeeVerseStatus.PARTIAL)
        missing_all = sum(1 for c in self._capabilities if c.beeverse_status == BeeVerseStatus.MISSING)
        overall_pct = (installed_all + 0.5 * partial_all) / total_all * 100 if total_all > 0 else 0.0

        return {
            "dimensions": dimension_stats,
            "overall": {
                "total": total_all,
                "installed": installed_all,
                "partial": partial_all,
                "missing": missing_all,
                "coverage_pct": round(overall_pct, 2),
            },
        }

    def update_status(self, name: str, new_status: BeeVerseStatus, match: str = "") -> bool:
        cap = self._name_index.get(name)
        if cap is None:
            logger.warning("Capability not found: %s", name)
            return False
        cap.beeverse_status = new_status
        if match:
            cap.beeverse_match = match
        logger.info("Updated %s: %s (match=%s)", name, new_status.value, match)
        return True
